from jsonb_populate_recordset(null::public.date_ideas, '[{"slug":"sentosa-sunset-splurge","title":"Sentosa sunset splurge","tagline":"Cable car in, tall ship out","description":"Float over the harbour by cable car, blend a perfume for each other at Scentopia, then board the Royal Albatross for dinner at sea.","moods":["romantic","fancy"],"occasions":["anniversary","birthday"],"start_time":"15:00","stops":[{"slug":"cable-car"},{"slug":"scentopia"},{"slug":"royal-albatross"}],"position":1,"photo_url":"https://images.unsplash.com/photo-1625508133058-78bc39fbd228","photo_width":null,"photo_height":null},{"slug":"rainy-day-hideout","title":"Rainy-day hideout","tagline":"Tents, cats and matcha","description":"Rain plans that feel cosy. Indoor camping with cats in Orchard, a photobooth strip, then matcha desserts.","moods":["chill","playful","lowkey"],"occasions":["rainy-day","spontaneous"],"start_time":"13:00","stops":[{"slug":"me-cafe-games-orchard"},{"slug":"dollop-pitstop"},{"slug":"hvala"}],"position":2,"photo_url":"https://images.unsplash.com/photo-1636070759654-5c93bbca2862","photo_width":null,"photo_height":null},{"slug":"make-something-together","title":"Make something together","tagline":"Leave with a souvenir you made","description":"Start with a slow café brunch, sculpt each other something at Clayful, and finish with LEGO flowers that never wilt.","moods":["creative","chill"],"occasions":["first-date","weekend"],"start_time":"11:00","stops":[{"slug":"fyp-cafe"},{"slug":"clayful-cafe"},{"slug":"block-bouquets"}],"position":3,"photo_url":"https://images.unsplash.com/photo-1589051088132-06f36a22012a","photo_width":null,"photo_height":null},{"slug":"chinatown-after-dark","title":"Chinatown after dark","tagline":"Dinner in the dark, then dessert","description":"A mystery menu at NOX, a wander through the lanes, then desserts at Ri Ri Cha. Lots to talk about.","moods":["adventurous","romantic","foodie"],"occasions":["anniversary","spontaneous"],"start_time":"18:30",